// My lock, plus locks left behind by crashed runs
const processed = $('Products to translate').isExecuted && $('Products to translate').first().json.waiting > 0 && $('Translation report').isExecuted && $('Translation report').first().json.done > 0;
const ids = [$('Won the lock?').first().json.lockId, ...$('Lock state').first().json.stale];
return ids.map((id) => ({ json: { id, processed: !!processed } }));
